def add_about_stack(apps, schema_editor):
    """Marks the About page's tools, adding any that aren't in the list yet. Existing names, slugs and logos are left as they are."""
    Technology = apps.get_model('services', 'Technology')
    for order, (name, slug, group, use) in enumerate(ABOUT_STACK):
        tool = Technology.objects.filter(name__iexact=name).first() or Technology.objects.filter(slug=slug).first()
        if tool is None:
            tool = Technology(name=name, slug=slug if not Technology.objects.filter(slug=slug).exists() else slugify(f'{name}-tool'))
        tool.on_about_page = True
        tool.about_group = group
        tool.about_use = tool.about_use or use
        tool.about_order = order
        tool.save()


